<script setup>
import {nextTick,onBeforeUnmount,ref,watch} from 'vue';
import {onBeforeRouteLeave} from 'vue-router';
import {request} from '../../api/http';
import {session} from '../../lib/session';
import {createClientInfoReader} from '../../api/client-info';
import {safeFileUrl} from '../../lib/client-profile-sections';
const props=defineProps({bundle:Object,name:String});const open=defineModel({type:Boolean,default:false});const emit=defineEmits(['saved','busy']);
const file=ref(null),preview=ref(''),camera=ref(false),video=ref(null),canvas=ref(null),busy=ref(false),error=ref(''),notice=ref('');let stream;
function stop(){stream?.getTracks().forEach(t=>t.stop());stream=null;camera.value=false;}
function clear(){if(preview.value)URL.revokeObjectURL(preview.value);preview.value='';file.value=null;stop();}
function choose(blob){if(!blob?.type?.startsWith('image/')){error.value='Please choose an image file.';return;}if(blob.size>10*1024*1024){error.value='Photo must be below 10 MB.';return;}clear();file.value=blob;preview.value=URL.createObjectURL(blob);error.value='';notice.value='Photo ready. Click Save profile photo.';}
async function startCamera(){error.value='';try{stop();if(!navigator.mediaDevices?.getUserMedia)throw Error('Camera is not available in this browser.');stream=await navigator.mediaDevices.getUserMedia({video:{facingMode:'user'},audio:false});if(!open.value){stop();return;}camera.value=true;await nextTick();video.value.srcObject=stream;await video.value.play();}catch(e){stop();error.value='Camera not available: '+e.message;}}
function capture(){const c=canvas.value,v=video.value;c.width=v.videoWidth||640;c.height=v.videoHeight||480;c.getContext('2d').drawImage(v,0,0,c.width,c.height);c.toBlob(blob=>{if(blob&&open.value)choose(blob);else error.value='Unable to capture the photo.';},'image/jpeg',.88);}
async function save(){if(!file.value||busy.value)return;busy.value=true;emit('busy',true);error.value='';try{const formData=new FormData(),ext=file.value.type==='image/png'?'png':file.value.type==='image/webp'?'webp':'jpg';formData.append('file',file.value,'client_profile_'+Date.now()+'.'+ext);formData.append('is_private','0');formData.append('folder','Home/Attachments');formData.append('doctype','Patient');formData.append('docname',props.bundle.pid);const body=await request('upload_file',{formData,csrfToken:session.csrf_token});const url=safeFileUrl(body.message?.file_url);if(!url)throw Error('Photo upload failed.');await createClientInfoReader().call('frappe.client.set_value',{doctype:'Patient',name:props.bundle.pid,fieldname:'custom_client_photo',value:url});props.bundle.patient.custom_client_photo=url;delete props.bundle.lazy.docs;emit('saved',url);open.value=false;}catch(e){error.value=e.message;}finally{busy.value=false;emit('busy',false);}}
watch(open,value=>{if(!value)clear();else{clear();error.value='';notice.value='';}});
onBeforeRouteLeave(()=>!busy.value);onBeforeUnmount(clear);
</script>
<template><div v-if="open" class="client-photo-upload-overlay" role="dialog" aria-modal="true" aria-label="Profile photo" @click.self="!busy&&(open=false)" @keydown.esc.stop="!busy&&(open=false)"><section class="c3-profile-upload-box"><header><h3>Client profile photo</h3><button type="button" class="c3-btn" :disabled="busy" aria-label="Close photo uploader" @click="open=false">×</button></header><p>{{name}} — choose a photo file or use the camera, then save.</p><div class="c3-profile-preview"><img v-if="preview" :src="preview" alt="New profile photo"><span v-else>👤</span></div><input type="file" class="c3-profile-file" accept="image/*" :disabled="busy" @change="choose($event.target.files?.[0])"><button type="button" class="c3-btn c3-profile-camera-btn" :disabled="busy" @click="startCamera">Use camera</button><div v-if="camera" class="c3-profile-camera-wrap"><video ref="video" autoplay playsinline muted></video><button type="button" class="c3-btn" @click="capture">Capture photo</button><button type="button" class="c3-btn" @click="stop">Cancel camera</button></div><canvas ref="canvas" hidden></canvas><p v-if="error" role="alert" class="c3-profile-status err">{{error}}</p><p v-if="notice" role="status" class="c3-profile-status">{{notice}}</p><button type="button" class="c3-btn c3-btn-primary c3-profile-save" :disabled="!file||busy" @click="save">{{busy?'Uploading photo…':'Save profile photo'}}</button></section></div></template>
<style scoped>.client-photo-upload-overlay{position:fixed;inset:0;z-index:10000;background:#1239;display:grid;place-items:center;padding:15px}.c3-profile-upload-box{background:#fffdf5;border:1px solid #bba35e;border-radius:12px;padding:20px;width:min(600px,95vw);max-height:90dvh;overflow:auto}.c3-profile-upload-box header{display:flex;justify-content:space-between}.c3-profile-preview{display:grid;place-items:center;min-height:140px;background:#eef2e7}.c3-profile-preview img,.c3-profile-camera-wrap video{max-width:100%;max-height:45vh}.c3-profile-preview span{font-size:70px}.c3-profile-file{display:block;max-width:100%;margin:12px 0}</style>
